const config = $input.first().json;
if (typeof config.atlasBaseUrl !== 'string') throw new Error('Set atlasBaseUrl in Owner configuration.');
// Pure JavaScript: no URL global or imported module is required by the n8n sandbox.
const match = /^(https?):\/\/(localhost|127\.0\.0\.1|\[::1\]|[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)*)(?::([0-9]{1,5}))?\/?$/i.exec(config.atlasBaseUrl);
if (!match) throw new Error('Use an Atlas origin only, without credentials, path, query or fragment.');
const protocol = match[1].toLowerCase();
const hostname = match[2].toLowerCase();
const port = match[3];
if (hostname.length > 253 || (port && (Number(port) < 1 || Number(port) > 65535))) throw new Error('Invalid Atlas origin.');
const local = ['localhost', '127.0.0.1', '[::1]'].includes(hostname);
if (protocol !== 'https' && !(local && protocol === 'http')) throw new Error('Use HTTPS, or HTTP loopback for local testing only.');
if (hostname.endsWith('.example.test') || hostname === 'example.test' || hostname === 'example.com') throw new Error('Replace the example origin with your authorised Atlas origin.');
const origin = protocol + '://' + hostname + (port ? ':' + port : '');
return [{ json: { requestUrl: origin + '/api/boxsafe/daily-briefing' } }];

const response = $input.first().json;
if (response.statusCode !== 200) throw new Error('Atlas briefing request did not succeed.');
const briefing = response.body;
if (!briefing || !['fake', 'live'].includes(briefing.mode)) {
  throw new Error('Briefing sources are mixed, unavailable or missing provenance.');
}
if (typeof briefing.spoken !== 'string' || !briefing.spoken.trim() || typeof briefing.dataNotice !== 'string' || !briefing.dataNotice.trim()) {
  throw new Error('Atlas did not return spoken text and a data notice.');
}
if (briefing.mode === 'fake' && (!/fictional/i.test(briefing.spoken) || !/fictional/i.test(briefing.dataNotice))) {
  throw new Error('Fictional figures must remain labelled in both text and speech.');
}
return [{ json: {
  mode: briefing.mode,
  fixture: briefing.mode === 'fake',
  dataNotice: briefing.dataNotice,
  spoken: briefing.spoken,
  generatedAt: briefing.generatedAt ?? null,
  delivery: 'Prepared only. No notification, email or call was sent.'
} }];
